+/* ---------------------------------------------------------------- */
 /* Surfaces — the six catalog cards                                  */
 /* ---------------------------------------------------------------- */

 .surface {
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 22px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-raised);
   box-shadow: var(--hairline);
 }

 .surface__head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
 }

 .surface__id {
   font-family: var(--mono);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--accent);
 }

 .surface__statement {
   font-size: 0.9375rem;
   font-weight: 500;
   line-height: 1.5;
 }

 .surface__meta {
   display: flex;
   flex-wrap: wrap;
   gap: 6px;
 }

 .surface__scores {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   gap: 4px 10px;
   font-family: var(--mono);
   font-size: 0.8125rem;
   color: var(--muted);
 }

 .surface__opportunity {
   font-size: 1.375rem;
   font-weight: 600;
   letter-spacing: -0.02em;
   color: var(--text);
 }

 .meter {
   display: flex;
   flex-direction: column;
   gap: 6px;
 }

 .meter__head {
   display: flex;
   justify-content: space-between;
   font-size: 0.6875rem;
   letter-spacing: 0.07em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .meter__track {
+  display: block;
   height: 6px;
   border-radius: var(--r-pill);
   background: var(--surface-hover);
   overflow: hidden;
 }

 .meter__fill {
+  display: block;
   height: 100%;
   border-radius: var(--r-pill);
   background: var(--accent);
 }

 .meter__fill--positive { background: var(--green); }
 .meter__fill--warning { background: var(--amber); }

 .surface-card {
   container-type: inline-size;
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   transition:
     transform 0.2s var(--ease-apple-out),
     border-color 0.2s var(--ease-apple-out);
 }

 .surface-card:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
 }

 .surface-card__head {
   display: flex;
   align-items: baseline;
   justify-content: space-between;
   gap: 12px;
 }

 .surface-card__title {
   font-size: 1rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .surface-card__type {
   font-family: var(--mono);
   font-size: 0.6875rem;
   color: var(--faint);
 }

 .surface-card__blurb {
+  margin-top: auto;
   color: var(--muted);
   font-size: 0.875rem;
   line-height: 1.55;
 }

 .surface-card .surface {
   background: var(--bg-raised);
