 /* =====================================================================
    Agentic ODI — the site design system.

    Colours, radii, and easings live in assets/tokens.css, generated from
    the Living Studio's own theme so the site and the product are the same
    visual language. This file holds layout, type, components, and motion.

    Rule: no hex colour here. Everything is a var(--…) reference.
    ===================================================================== */

 /* ---------------------------------------------------------------- */
 /* Reset                                                            */
 /* ---------------------------------------------------------------- */

 *,
 *::before,
 *::after {
   box-sizing: border-box;
 }

 html {
   -webkit-text-size-adjust: 100%;
   scroll-behavior: smooth;
   scroll-padding-top: 96px;
 }

 body,
 h1, h2, h3, h4, p, figure, blockquote, dl, dd, ul, ol {
   margin: 0;
 }

 ul[class], ol[class] {
   list-style: none;
   padding: 0;
 }

 img, svg, video {
   display: block;
   max-width: 100%;
 }

 button, input, select, textarea {
   font: inherit;
   color: inherit;
 }

 button {
   cursor: pointer;
   border: 0;
   background: none;
 }

 a {
   color: var(--accent);
   text-decoration: none;
 }

 a:hover {
   color: var(--text);
 }

 :focus-visible {
   outline: 2px solid var(--accent);
   outline-offset: 3px;
   border-radius: 4px;
 }

 ::selection {
   background: var(--accent-strong);
   color: var(--text);
 }

 /* ---------------------------------------------------------------- */
 /* Base                                                             */
 /* ---------------------------------------------------------------- */

 body {
   min-height: 100vh;
   background: var(--bg);
   color: var(--text);
   font-family: var(--font);
   font-size: 1.0625rem;
   line-height: 1.65;
   -webkit-font-smoothing: antialiased;
   -moz-osx-font-smoothing: grayscale;
   overflow-x: hidden;
 }

 /* The canvas. The Studio's own two radial washes — depth without imagery. */
 body::before {
   content: "";
   position: fixed;
   inset: 0;
   z-index: -1;
   pointer-events: none;
   background:
     radial-gradient(
       760px 420px at 50% 108%,
       color-mix(in srgb, var(--accent-strong) 9%, transparent),
       transparent 72%
     ),
     radial-gradient(
       900px 520px at 68% -12%,
       color-mix(in srgb, var(--accent-strong) 8%, transparent),
       transparent 68%
     );
 }

 .skip-link {
   position: absolute;
   left: 16px;
   top: -60px;
   z-index: 100;
   padding: 10px 16px;
   border-radius: var(--r-md);
   background: var(--accent);
   color: var(--accent-ink);
   font-size: 0.875rem;
   font-weight: 600;
   transition: top 0.15s var(--ease-tactile);
 }

 .skip-link:focus {
   top: 16px;
   color: var(--accent-ink);
 }

 .sr-only {
   position: absolute;
   width: 1px;
   height: 1px;
   padding: 0;
   margin: -1px;
   overflow: hidden;
   clip: rect(0, 0, 0, 0);
   white-space: nowrap;
   border: 0;
 }

 /* ---------------------------------------------------------------- */
 /* Type scale                                                       */
 /* ---------------------------------------------------------------- */

 .eyebrow {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   margin: 0 0 20px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.18em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .eyebrow--pill {
   padding: 6px 14px;
   border: 1px solid var(--line-strong);
   border-radius: var(--r-pill);
   background: var(--surface);
   color: var(--muted);
 }

 .display {
   text-wrap: balance;
   font-size: clamp(2.75rem, 7.5vw, 6rem);
   font-weight: 600;
   letter-spacing: -0.04em;
   line-height: 0.98;
 }

 .section__title {
   max-width: 20ch;
   text-wrap: balance;
   font-size: clamp(1.875rem, 4vw, 3.25rem);
   font-weight: 600;
   letter-spacing: -0.03em;
   line-height: 1.06;
 }

 .section__title--wide {
   max-width: 28ch;
 }

 .lead {
   max-width: 52ch;
   font-size: clamp(1.0625rem, 1.5vw, 1.375rem);
   line-height: 1.5;
   color: var(--muted);
 }

 .prose {
   max-width: var(--w-prose);
   color: var(--muted);
 }

 .prose > * + * {
   margin-top: 1.15em;
 }

 .prose strong {
   color: var(--text);
