 }

 .prose h3 {
   margin-top: 1.8em;
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   color: var(--text);
 }

 .prose ul, .prose ol {
   padding-left: 1.25em;
 }

 .prose li + li {
   margin-top: 0.4em;
 }

 .prose blockquote {
   padding-left: 1em;
   border-left: 2px solid var(--line-strong);
   color: var(--muted);
   font-style: italic;
 }

 .prose table {
   width: 100%;
   border-collapse: collapse;
   font-size: 0.9375rem;
 }

 .prose th, .prose td {
   padding: 10px 14px;
   border-bottom: 1px solid var(--line);
   text-align: left;
   vertical-align: top;
 }

 .prose th {
   color: var(--text);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.09em;
   text-transform: uppercase;
