 }

 .label {
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .mono {
   font-family: var(--mono);
 }

 /* ---------------------------------------------------------------- */
 /* Layout                                                           */
 /* ---------------------------------------------------------------- */

 .shell {
   width: 100%;
   max-width: var(--w-page);
   margin-inline: auto;
   padding-inline: var(--gutter);
 }

 .shell--wide {
   max-width: var(--w-wide);
 }

 .section {
   padding-block: var(--section-y);
 }

 .section + .section {
   border-top: 1px solid var(--line);
 }

 .section__head {
   display: flex;
   flex-direction: column;
   gap: 20px;
   margin-bottom: clamp(40px, 6vw, 72px);
 }

 .grid {
   display: grid;
   gap: 20px;
 }

 .grid--2 { grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); }
 .grid--3 { grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); }
 .grid--4 { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }

 .stack {
   display: flex;
   flex-direction: column;
   gap: 16px;
 }

 .cluster {
   display: flex;
   flex-wrap: wrap;
   gap: 10px;
   align-items: center;
 }

 /* ---------------------------------------------------------------- */
 /* Header & footer                                                  */
 /* ---------------------------------------------------------------- */

 .site-header {
   position: sticky;
   top: 0;
   z-index: 50;
   border-bottom: 1px solid var(--line);
   background: color-mix(in srgb, var(--bg) 72%, transparent);
   backdrop-filter: blur(16px) saturate(180%);
   -webkit-backdrop-filter: blur(16px) saturate(180%);
 }

 .site-header__inner {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 20px;
   width: 100%;
   max-width: var(--w-page);
   margin-inline: auto;
   padding: 14px var(--gutter);
 }

 .brand {
   display: inline-flex;
   align-items: center;
   gap: 10px;
   color: var(--text);
 }

 .brand:hover { color: var(--text); }

 .brand__name {
   font-size: 0.9375rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .site-nav {
   display: flex;
   gap: 24px;
   font-size: 0.875rem;
   color: var(--muted);
 }

 .site-nav a:hover {
   color: var(--text);
 }

 .site-footer {
   border-top: 1px solid var(--line);
   padding-block: clamp(48px, 7vw, 88px);
   color: var(--faint);
   font-size: 0.875rem;
 }

 .site-footer__top {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   justify-content: space-between;
   gap: 12px 24px;
   margin-bottom: 28px;
 }

 .site-footer__brand {
   display: inline-flex;
   align-items: center;
   gap: 10px;
   color: var(--text);
 }

 .site-footer__tagline {
   color: var(--muted);
 }

 .site-footer__nav {
   display: flex;
   flex-wrap: wrap;
   gap: 8px 24px;
   margin-bottom: 28px;
 }

 .site-footer__nav a {
   color: var(--muted);
 }

 .site-footer__nav a:hover {
   color: var(--text);
 }

 .site-footer__legal {
   color: var(--faint);
 }

 .site-footer__note {
   margin-top: 6px;
   color: var(--faint);
 }

 /* ---------------------------------------------------------------- */
 /* Buttons, pills, cards                                            */
 /* ---------------------------------------------------------------- */

 .btn {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   gap: 8px;
   padding: 13px 24px;
   border: 1px solid transparent;
   border-radius: var(--r-pill);
   font-size: 0.9375rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   transition:
     transform 0.15s var(--ease-tactile),
     background-color 0.15s var(--ease-tactile),
     border-color 0.15s var(--ease-tactile),
     opacity 0.15s var(--ease-tactile);
 }

 .btn--primary {
   background: var(--accent);
   color: var(--accent-ink);
 }

 .btn--primary:hover {
   color: var(--accent-ink);
   transform: translateY(-1px);
   opacity: 0.92;
 }

 .btn--ghost {
   border-color: var(--line-strong);
   background: var(--surface);
   color: var(--text);
 }

 .btn--ghost:hover {
   color: var(--text);
   transform: translateY(-1px);
   background: var(--surface-hover);
 }

 .btn--sm {
   padding: 9px 18px;
   font-size: 0.875rem;
 }

 .btn:active {
   transform: scale(0.98);
 }

 .pill {
   display: inline-flex;
   align-items: center;
   gap: 6px;
   padding: 3px 10px;
   border: 1px solid var(--line-strong);
   border-radius: var(--r-pill);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.06em;
   text-transform: uppercase;
   color: var(--muted);
   white-space: nowrap;
 }

 .pill--accent {
   border-color: color-mix(in srgb, var(--accent) 34%, transparent);
   background: color-mix(in srgb, var(--accent) 12%, transparent);
   color: var(--accent);
 }

 .pill--positive {
   border-color: color-mix(in srgb, var(--green) 28%, transparent);
   background: color-mix(in srgb, var(--green) 10%, transparent);
   color: var(--green);
 }

 .pill--warning {
   border-color: color-mix(in srgb, var(--amber) 30%, transparent);
   background: color-mix(in srgb, var(--amber) 10%, transparent);
   color: var(--amber);
 }

 .card {
   padding: 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   transition:
     transform 0.2s var(--ease-apple-out),
     border-color 0.2s var(--ease-apple-out),
     background-color 0.2s var(--ease-apple-out);
 }

 .card:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
   background: var(--surface-hover);
 }

 .card__title {
   font-size: 1.0625rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .card__body {
   margin-top: 10px;
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .glass {
   border: 1px solid var(--line-strong);
   border-radius: var(--r-lg);
   background: var(--glass);
   backdrop-filter: var(--glass-blur);
   -webkit-backdrop-filter: var(--glass-blur);
   box-shadow: var(--hairline), 0 40px 120px -20px rgba(0, 0, 0, 0.85);
 }

 /* ---------------------------------------------------------------- */
 /* Hero                                                             */
 /* ---------------------------------------------------------------- */

 .hero {
   display: flex;
   align-items: center;
   min-height: calc(100svh - 68px);
   padding-block: clamp(72px, 11vw, 140px);
   text-align: center;
 }

 .hero__inner {
   display: flex;
   flex-direction: column;
   align-items: center;
   gap: 24px;
 }

 .hero__title {
   max-width: 20ch;
   text-wrap: balance;
   font-size: clamp(2.75rem, 7.5vw, 6rem);
   font-weight: 600;
   letter-spacing: -0.04em;
   line-height: 0.98;
 }

 .hero__sub {
   max-width: 46ch;
   color: var(--muted);
   font-size: clamp(1.0625rem, 1.6vw, 1.375rem);
   line-height: 1.5;
 }

 .hero__actions {
   display: flex;
   flex-wrap: wrap;
   justify-content: center;
   gap: 12px;
   margin-top: 8px;
 }

 .hero__cue {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   margin-top: 12px;
   color: var(--faint);
   font-size: 0.8125rem;
 }

 .hero__cue span {
   display: block;
   width: 1px;
   height: 22px;
   background: linear-gradient(to bottom, var(--line-strong), transparent);
 }

 /* ---------------------------------------------------------------- */
 /* Problem                                                          */
 /* ---------------------------------------------------------------- */

 .beats {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
 }

 .beat {
   display: flex;
   flex-direction: column;
   gap: 12px;
   padding: 26px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
 }

 .beat__quote {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   line-height: 1.35;
 }

 .beat__support {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .closer {
   margin-top: 40px;
   max-width: 34ch;
   font-size: clamp(1.375rem, 2.4vw, 2rem);
   font-weight: 600;
   letter-spacing: -0.025em;
   line-height: 1.2;
   color: var(--text);
 }

 /* ---------------------------------------------------------------- */
 /* Insight — the formula                                            */
 /* ---------------------------------------------------------------- */

 .insight {
   display: grid;
   gap: clamp(40px, 6vw, 72px);
   grid-template-columns: minmax(0, 1fr);
   align-items: start;
 }

 @media (min-width: 960px) {
   .insight {
-    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
+    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
   }
 }

 .formula {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   gap: 10px;
+  overflow-x: auto;
   padding: 22px 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-sunken);
   font-family: var(--mono);
-  font-size: clamp(0.9375rem, 1.6vw, 1.125rem);
+  font-size: clamp(0.875rem, 1.35vw, 1rem);
   line-height: 1.5;
 }

 .formula__label {
   color: var(--muted);
 }

 .formula__expr {
   color: var(--text);
+  white-space: nowrap;
 }

 .formula__gap {
   color: var(--accent);
 }

 .statline {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   gap: 8px 12px;
   margin-top: 20px;
   font-size: 0.9375rem;
 }

 .statline__value {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .statline__source {
   color: var(--faint);
 }

 /* The importance/satisfaction gap, drawn honestly. */
 .gap {
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
 }

 .gap__row {
   display: grid;
   grid-template-columns: 96px 1fr 40px;
   align-items: center;
   gap: 14px;
   font-size: 0.8125rem;
   color: var(--muted);
 }

 .gap__track {
+  display: block;
   height: 8px;
   border-radius: var(--r-pill);
   background: var(--surface-hover);
   overflow: hidden;
 }

 .gap__fill {
+  display: block;
   height: 100%;
   border-radius: var(--r-pill);
   background: var(--accent-strong);
 }

 .gap__fill--satisfaction {
   background: color-mix(in srgb, var(--muted) 55%, transparent);
 }

 .gap__value {
   font-family: var(--mono);
   font-size: 0.8125rem;
   text-align: right;
   color: var(--text);
 }

 .gap__note {
   color: var(--faint);
   font-size: 0.8125rem;
   line-height: 1.5;
 }

 /* ---------------------------------------------------------------- */
 /* The demo — the Living Studio, running its script                  */
 /* ---------------------------------------------------------------- */

 .demo {
   display: flex;
   flex-direction: column;
